#[test]
fn test_no_fusion_outside_triggered_image_pages() {
    crate::testport::assert_eq(of_active(0, 1, 1), 0, "PDF and born digital never fuse");
    crate::testport::assert_eq(of_active(1, 0, 1), 0, "untriggered image never fuses");
    crate::testport::assert_eq(of_active(1, 1, 0), 0, "keyword gate is stacked");
    crate::testport::assert_eq(of_active(1, 1, 1), 1, "photo lane");
    crate::testport::assert_eq(of_active(1, 2, 1), 1, "thermal lane");
}
#[test]
